> +		return NULL;
> +
> +	for (offset = info->cap_offset; offset; offset = hdr->next) {
> +		hdr = (void *)info + offset;
> +		if (hdr->id == VFIO_REGION_INFO_CAP_SPARSE_MMAP)
> +			return (struct vfio_region_info_cap_sparse_mmap *)hdr;
> +	}
